files.content:
.tooltip-wrap{
  position:relative;
  display:inline-flex;
}
.tooltip{
  position:absolute;
  bottom:calc(100% + var(--s-1));
  left:50%;
  transform:translate(-50%, 2px);
  z-index:var(--z-popover);
  max-width:var(--w-tooltip);
  width:max-content;
  padding:var(--s-1) var(--s-2);
  background:var(--obsidian-800);
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-sm);
  box-shadow:var(--sh-2);
  font-family:var(--font-sans);
  font-size:var(--t-caption);
  line-height:var(--lh-snug);
  color:var(--obsidian-100);
  opacity:0;
  pointer-events:none;
  transition:opacity var(--d-quick) var(--ease-standard), transform var(--d-quick) var(--ease-standard);
}
.tooltip.is-open{
  opacity:1;
  transform:translate(-50%, 0);
}
.tooltip-bottom{
  bottom:auto;
  top:calc(100% + var(--s-1));
  transform:translate(-50%, -2px);
}
.tooltip-bottom.is-open{
  transform:translate(-50%, 0);
}
.tooltip-end{
  left:auto;
  right:0;
  transform:translate(0, 2px);
}
.tooltip-end.is-open{
  transform:translate(0, 0);
}
.tooltip-bottom.tooltip-end{
  transform:translate(0, -2px);
}
.tooltip-bottom.tooltip-end.is-open{
  transform:translate(0, 0);
}
